
// --- VERİ MODELLERİ ---

// 1. Soru Modeli
class Question {
  final String text;
  final List<String> options;
  final int correctIndex;

  Question({
    required this.text,
    required this.options,
    required this.correctIndex,
  });
}

// 2. Konu Modeli (Başlık + Senin Yazacağın Notlar + Sorular)
class TopicContent {
  final String id;
  final String title;
  final String lectureNote; // <-- İşte senin yazıların buraya gelecek
  final List<Question> questions;

  TopicContent({
    required this.id,
    required this.title,
    required this.lectureNote,
    required this.questions,
  });
}

// --- VERİ TABANI (DEPO) ---
