  // Bu fonksiyon ders adına göre (Tarih, Coğrafya) konuları getirir
  static List<TopicContent> getTopicsForLesson(String lessonName) {
    if (lessonName == 'Tarih') {
      return _historyTopics;
    } else if (lessonName == 'Coğrafya') {
      return _geoTopics;
    } else if (lessonName == 'Vatandaşlık') {
      return _citizenshipTopics;
    }
    return [];
  }

  // --- TARİH KONULARI VE İÇERİKLERİ ---
